pub(crate) fn test_get_export_file<'p>(config_path: Option<&Path>) -> Result<(ExportFile<'p>, Vec<String>), Box<dyn Error>> {
    let config_file = match config_path {
        None => Config {
            export_file_path: Some(PathBuf::from("test_resources/Empty/export")),
            use_stdin: false,
            permitted_axioms: Some(Vec::new()),
            unpermitted_axiom_hard_error: true,
            nat_extension: false,
            string_extension: false,

test_export_file(None, |export| {
    let mut rng = thread_rng();
    export.with_ctx(|ctx| {
        for size in 0..100 {
            for _ in 0..100 {
                let s = rand_string(&mut rng, size);
                let (l, r) = (ctx.mk_string_lit_quick(s.clone()), ctx.mk_string_lit_quick(s));
                assert_eq!(hash64!(l), hash64!(r));
                assert_eq!(l, r)
            }
            for _ in 0..100 {
                let s = rng.gen_biguint(size as u64);
                let (l, r) = (ctx.mk_nat_lit_quick(s.clone()), ctx.mk_nat_lit_quick(s));
                assert_eq!(hash64!(l), hash64!(r));
                assert_eq!(l, r)
            }

pub fn mk_string_lit_quick(&mut self, s: CowStr<'t>) -> Option<ExprPtr<'t>> {
    if !self.export_file.config.string_extension {
        return None
    }
    let string_ptr = self.alloc_string(s);
    self.mk_string_lit(string_ptr)

pub fn mk_nat_lit(&mut self, num_ptr: BigUintPtr<'t>) -> Option<ExprPtr<'t>> {
    if !self.export_file.config.nat_extension {
        return None
    }
    let hash = hash64!(crate::expr::NAT_LIT_HASH, num_ptr);
    Some(self.alloc_expr(Expr::NatLit { ptr: num_ptr, hash }))
}

/// Shortcut to make an `Expr::NatLit` directly from a `BigUint`, rather than
/// going `alloc_bignum` and `mk_nat_lit`
pub fn mk_nat_lit_quick(&mut self, n: BigUint) -> Option<ExprPtr<'t>> {
    let num_ptr = self.alloc_bignum(n)?;
    self.mk_nat_lit(num_ptr)

pub(crate) fn infer(&mut self, e: ExprPtr<'t>, flag: InferFlag) -> ExprPtr<'t> {
    if let Some(cached) = self.tc_cache.infer_cache_check.get(&e).copied() {
        return cached
    }
    if flag == InferFlag::InferOnly {
        if let Some(cached) = self.tc_cache.infer_cache_no_check.get(&e).copied() {
            return cached
        }
    }

pub fn def_eq(&mut self, x: ExprPtr<'t>, y: ExprPtr<'t>) -> bool {
    if let Some(easy) = self.def_eq_quick_check(x, y) {
        return easy
    }
    let defeq_fail_cache_key = (x, y, self.ctx.eager_mode);
    if self.tc_cache.defeq_fail_cache.contains(&defeq_fail_cache_key) {
        return false
    }
